Prova SQL NUOVA della 750 (sei controlli: colonna timestamptz nullable senza valore di partenza, lettura della rotta di avvio con applicazione in corso / finita / vecchia, rimetti pronto col segno a NULL). Eseguita sul Postgres locale: senza la 750 psql esce 3 (P0001, «manca applicazione_finita_il»), con la 750 esce 0. Diff esatto (file nuovo):
diff --git a/tests/sql/rls/riparazione-r13-segno-di-fine-applicazione.test.sql b/tests/sql/rls/riparazione-r13-segno-di-fine-applicazione.test.sql
new file mode 100644
index 00000000..d44751aa
--- /dev/null
+++ b/tests/sql/rls/riparazione-r13-segno-di-fine-applicazione.test.sql
@@ -0,0 +1,120 @@
+-- =============================================================================
+-- R13-001 · R13-009 — Il lavoro AI sul catalogo applicato ha il segno di fine (750)
+-- =============================================================================
+--   tests/sql/harness/apply.sh mycity_test && tests/sql/harness/run.sh mycity_test
+--
+-- Le rotte scrivono con la chiave di servizio: qui si scrive come loro (senza
+-- RLS) e si guarda cosa tiene il database.
+-- ① la colonna applicazione_finita_il c'è, è un timestamptz, accetta NULL e non
+--    ha un valore di partenza (un lavoro nuovo nasce senza segno)
+-- ② un lavoro appena prenotato da /apply ('applied', senza segno, di adesso) è
+--    quello che la lettura della rotta di avvio trova «in applicazione»
+-- ③ scritto il segno di fine, la stessa lettura non trova più niente
+-- ④ un lavoro applicato senza segno ma vecchio (righe di prima della 750) non
+--    conta come applicazione in corso
+-- ⑤ /apply rimette il lavoro 'ready' col segno a NULL, e il database lo accetta
+-- Senza la 750 ① è rosso, e gli altri non si possono fare. ROLLBACK finale.
+-- =============================================================================
+
+BEGIN;
+
+SET LOCAL mycity.allow_profile_write = '1';
+
+CREATE TEMP TABLE esiti (nome text, ok boolean, dettaglio text) ON COMMIT DROP;
+
+INSERT INTO auth.users (id, email, raw_user_meta_data) VALUES
+  ('75075075-0000-0000-0000-000000000001', 'bottega-r13-segno@test.it', '{"role":"seller"}');
+
+-- ① la colonna
+INSERT INTO esiti
+SELECT 'la colonna del segno di fine c''è, timestamptz, nullable, senza valore di partenza',
+       coalesce(bool_and(data_type = 'timestamp with time zone' AND is_nullable = 'YES' AND column_default IS NULL), false),
+       coalesce(string_agg(data_type || ' · nullable ' || is_nullable || ' · default ' || coalesce(column_default, 'nessuno'), '; '),
+                'manca applicazione_finita_il su catalog_ai_jobs: la 750 non è passata')
+  FROM information_schema.columns
+ WHERE table_schema = 'public' AND table_name = 'catalog_ai_jobs' AND column_name = 'applicazione_finita_il';
+
+DO $$
+DECLARE
+  presente boolean;
+  trovato uuid;
+  segno timestamptz;
+  stato text;
+  -- La lettura della rotta di avvio: l'ultimo applicato del negozio, poi «senza segno e di meno di 120 s».
+  lettura constant text := $q$
+    SELECT id FROM (
+      SELECT id, updated_at, applicazione_finita_il
+        FROM public.catalog_ai_jobs
+       WHERE seller_id = '75075075-0000-0000-0000-000000000001' AND status = 'applied'
+       ORDER BY updated_at DESC
+       LIMIT 1
+    ) ultimo
+     WHERE applicazione_finita_il IS NULL AND updated_at > now() - interval '120 seconds'
+  $q$;
+BEGIN
+  SELECT EXISTS (
+    SELECT 1 FROM information_schema.columns
+     WHERE table_schema = 'public' AND table_name = 'catalog_ai_jobs' AND column_name = 'applicazione_finita_il'
+  ) INTO presente;
+  IF NOT presente THEN
+    RETURN;
+  END IF;
+
+  -- Un lavoro di ieri, applicato senza segno (com'erano tutti prima della 750).
+  INSERT INTO public.catalog_ai_jobs (id, seller_id, operation, status, created_at, updated_at)
+  VALUES ('b7507507-0000-0000-0000-000000000001', '75075075-0000-0000-0000-000000000001',
+          'improve', 'applied', now() - interval '1 day', now() - interval '1 day');
+  -- ④
+  EXECUTE lettura INTO trovato;
+  INSERT INTO esiti VALUES ('un applicato vecchio senza segno non è un applicazione in corso', trovato IS NULL,
+                            coalesce('trovato ' || trovato::text, 'nessuno'));
+
+  -- Un lavoro pronto da rivedere, nato senza segno.
+  INSERT INTO public.catalog_ai_jobs (id, seller_id, operation, status)
+  VALUES ('b7507507-0000-0000-0000-000000000002', '75075075-0000-0000-0000-000000000001', 'redescribe', 'ready');
+  EXECUTE 'SELECT applicazione_finita_il FROM public.catalog_ai_jobs WHERE id = $1'
+     INTO segno USING 'b7507507-0000-0000-0000-000000000002'::uuid;
+  INSERT INTO esiti VALUES ('un lavoro nuovo nasce senza segno di fine', segno IS NULL, coalesce(segno::text, 'NULL'));
+
+  -- ② /apply lo prenota: 'applied', updated_at adesso, il segno non lo tocca.
+  UPDATE public.catalog_ai_jobs SET status = 'applied', updated_at = now()
+   WHERE id = 'b7507507-0000-0000-0000-000000000002' AND status = 'ready';
+  EXECUTE lettura INTO trovato;
+  INSERT INTO esiti VALUES ('il lavoro appena prenotato è un applicazione in corso',
+                            trovato = 'b7507507-0000-0000-0000-000000000002'::uuid,
+                            coalesce('trovato ' || trovato::text, 'nessuno'));
+
+  -- ⑤ un guasto di passaggio: /apply lo rimette pronto col segno a NULL.
+  BEGIN
+    EXECUTE 'UPDATE public.catalog_ai_jobs SET status = ''ready'', applicazione_finita_il = NULL, updated_at = now() WHERE id = $1'
+      USING 'b7507507-0000-0000-0000-000000000002'::uuid;
+    SELECT status INTO stato FROM public.catalog_ai_jobs WHERE id = 'b7507507-0000-0000-0000-000000000002';
+    INSERT INTO esiti VALUES ('rimesso pronto col segno a NULL', stato = 'ready', 'stato ' || stato);
+  EXCEPTION WHEN others THEN
+    INSERT INTO esiti VALUES ('rimesso pronto col segno a NULL', false, SQLSTATE);
+  END;
+
+  -- ③ riprenotato e finito: /apply scrive il segno.
+  UPDATE public.catalog_ai_jobs SET status = 'applied', updated_at = now()
+   WHERE id = 'b7507507-0000-0000-0000-000000000002' AND status = 'ready';
+  EXECUTE 'UPDATE public.catalog_ai_jobs SET applicazione_finita_il = now() WHERE id = $1'
+    USING 'b7507507-0000-0000-0000-000000000002'::uuid;
+  EXECUTE lettura INTO trovato;
+  INSERT INTO esiti VALUES ('col segno di fine l applicazione non è più in corso', trovato IS NULL,
+                            coalesce('trovato ' || trovato::text, 'nessuno'));
+END $$;
+
+DO $$
+DECLARE r record; rossi int;
+BEGIN
+  FOR r IN SELECT * FROM esiti ORDER BY nome LOOP
+    RAISE INFO '%  %  — %', CASE WHEN r.ok THEN 'ok  ' ELSE 'ROTTO' END, r.nome, r.dettaglio;
+  END LOOP;
+  SELECT count(*) INTO rossi FROM esiti WHERE ok IS NOT TRUE;
+  IF rossi > 0 THEN
+    RAISE EXCEPTION '% controllo/i rosso/i: il lavoro AI applicato non ha il segno di fine', rossi;
+  END IF;
+  RAISE INFO 'il segno di fine dell applicazione: % controlli verdi', (SELECT count(*) FROM esiti);
+END $$;
+
+ROLLBACK;

